from fastapi import FastAPI, Depends, HTTPException
from pydantic import BaseModel
import jwt
from datetime import datetime, timedelta
from config import settings

app = FastAPI()

# Define a Pydantic model for the JWT payload
class User(BaseModel):
    username: str
    password: str

# Define a dependency to get the current user from the JWT token
async def get_current_user(token: str = Depends(jwt.decode)) -> User:
    try:
        payload = jwt.decode(token, settings.SECRET_KEY, algorithms=[settings.ALGORITHM])
        return User(username=payload['username'], password=payload['password'])
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail='Token has expired')
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail='Invalid token')

# Define a route for user authentication
@app.post("/login")
async def login(user: User):
    # Authenticate user (this is a placeholder for actual authentication logic)
    if user.username == "your_username" and user.password == "your_password":
        access_token = jwt.encode({'username': user.username, 'password': user.password, 
                                    'exp': datetime.utcnow() + timedelta(hours=1)}, 
                                  settings.SECRET_KEY, algorithm=settings.ALGORITHM)
        return {"access_token": access_token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Define a route for protected access
@app.get("/protected")
async def protected_route(current_user: User = Depends(get_current_user)):
    return {"message": f"Hello, {current_user.username}!"}
